import{_ as s,c as n,o as l,ah as e}from"./chunks/framework.BrJYEL96.js";const b=JSON.parse('{"title":"链接与图片","description":"","frontmatter":{},"headers":[],"relativePath":"tmp/tmp.md","filePath":"tmp/tmp.md","lastUpdated":1792027243000}'),o={name:"tmp/tmp.md"};function t(p,a,r,c,d,i){return l(),n("div",null,a[0]||(a[0]=[e(`<h1 id="链接与图片" tabindex="-1">链接与图片 <a class="header-anchor" href="#链接与图片" aria-label="Permalink to &quot;链接与图片&quot;">​</a></h1><h2 id="图片处理" tabindex="-1">图片处理 <a class="header-anchor" href="#图片处理" aria-label="Permalink to &quot;图片处理&quot;">​</a></h2><h3 id="图像格式" tabindex="-1">图像格式 <a class="header-anchor" href="#图像格式" aria-label="Permalink to &quot;图像格式&quot;">​</a></h3><ul><li>网络带宽成本很高，图片处理在保证用户体验好的前提下，文件尺寸也要尽可能小</li><li>图片属性静态文件，不要放在 WEB 服务器上，而放在云储存服务器上并使用 CDN 加速</li><li>以 JPEG 类型优先使用，文件尺寸更小</li><li>小图片使用 PNG，清晰度更高，因为文件尺寸小，文件也不会太大</li><li>网页图标建议使用 css 字体构建如 <a href="https://www.iconfont.cn/" target="_blank" rel="noreferrer">iconfont</a> 或 <a href="https://fontawesome.com/icons?d=gallery" target="_blank" rel="noreferrer">fontawesome</a></li></ul><table tabindex="0"><thead><tr><th>格式</th><th>说明</th><th>透明</th></tr></thead><tbody><tr><td>PNG</td><td>无损压缩格式，适合图标、验证码等。有些小图标建议使用 css 字体构建。</td><td>支持</td></tr><tr><td>GIF</td><td>256 色，可以产生动画效果（即 GIF 动图）</td><td>支持</td></tr><tr><td>JPEG</td><td>有损压缩的类型，如商品、文章的图片展示</td><td></td></tr></tbody></table><p>下图的网站标志使用<code>png</code> 类型，这样图片清晰，同时有透明色，当页面底色改变时也不需要修改图片。</p><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-10-10/08/69520_33214_image-20190727162631092-20261010080423359.png" alt="image-20190727162631092" loading="lazy"></p><p>下面图片建议使用<code>jpeg</code> ，因为图片比较大使用 png 会造成文件过大，使用<code>jpeg</code>后尺寸不大而且清晰度也可以接受。</p><p><img src="https://www.houdunren.com/docs/images/1%20%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91/html/assets/image-20190727162835156.png" alt="image-20190727162835156" loading="lazy"></p><h4 id="保存透明图" tabindex="-1">保存透明图 <a class="header-anchor" href="#保存透明图" aria-label="Permalink to &quot;保存透明图&quot;">​</a></h4><p>下面介绍在<code>PhotoShop</code> 中快速生成透明 <code>png</code> 的图片效果。</p><ol><li>保证没有纯色的底</li></ol><p><img src="https://www.houdunren.com/docs/images/1%20%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91/html/assets/image-20190727163814195.png" alt="image-20190727163814195" loading="lazy"></p><ol><li>选择导出为 png 格式即可</li></ol><p><img src="https://raw.gitcode.com/loveagri/pic/raw/main/2026-10-10/08/37734_image-20190727163912804.png" alt="image-20190727163912804" loading="lazy"></p><h3 id="使用图片" tabindex="-1">使用图片 <a class="header-anchor" href="#使用图片" aria-label="Permalink to &quot;使用图片&quot;">​</a></h3><p>在网页中使用 <code>img</code> 标签展示图片，图片的大小、边框、倒角效果使用 css 处理。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">img</span><span style="color:#D19A66;"> src</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;/docs/images/1%20%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91/html/houdunren.png&quot;</span><span style="color:#D19A66;"> alt</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;后盾人&quot;</span><span style="color:#ABB2BF;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>src</td><td>图片地址</td></tr><tr><td>alt</td><td>图像打开异常时的替代文本</td></tr></tbody></table><h2 id="网页链接" tabindex="-1">网页链接 <a class="header-anchor" href="#网页链接" aria-label="Permalink to &quot;网页链接&quot;">​</a></h2><p>不能通过一个页面展示网站的所有功能，需要在不同页面中跳转，这就是链接所起到的功能。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span>&lt;a href=&quot;http://doc.houdunren.com&quot; target=&quot;_blank&quot; title=&quot;文档库&quot;&gt;后盾人文档库&lt;/a&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>href</td><td>跳转地址</td></tr><tr><td>target</td><td>_blank 新窗口打开 _self 当前窗口打开</td></tr><tr><td>title</td><td>链接提示文本</td></tr></tbody></table><h3 id="打开窗口" tabindex="-1">打开窗口 <a class="header-anchor" href="#打开窗口" aria-label="Permalink to &quot;打开窗口&quot;">​</a></h3><p>下面设置 target 属性在指定窗口打开。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;https://www.houdunren.com&quot;</span><span style="color:#D19A66;"> target</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;hdcms&quot;</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">        在IFRAME中打开</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">script</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#E5C07B;">	window</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">open</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;https://www.hdcms.com&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;hdcms&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/</span><span style="color:#E06C75;">script</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="锚点链接" tabindex="-1">锚点链接 <a class="header-anchor" href="#锚点链接" aria-label="Permalink to &quot;锚点链接&quot;">​</a></h3><p>锚点可以设置跳转到页面中的某个部分。</p><ol><li><p>为元素添加<code>id</code> 属性来设置锚点</p></li><li><p>设置 <code>a</code> 标签的 <code>href</code> 属性</p></li><li><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;#comment-1&quot;</span><span style="color:#ABB2BF;">&gt;跳转到评论区&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">div</span><span style="color:#D19A66;"> style</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;height: 1000px;&quot;</span><span style="color:#ABB2BF;">&gt;&lt;/</span><span style="color:#E06C75;">div</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">div</span><span style="color:#D19A66;"> id</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;comment-1&quot;</span><span style="color:#D19A66;"> style</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;background: green;&quot;</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">	这是后盾人评论内容区</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/</span><span style="color:#E06C75;">div</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div></li><li><p>也可以跳转到不同页面的锚点</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;article.html#comment-1&quot;</span><span style="color:#ABB2BF;">&gt;跳转到评论区&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><h3 id="邮箱链接" tabindex="-1">邮箱链接 <a class="header-anchor" href="#邮箱链接" aria-label="Permalink to &quot;邮箱链接&quot;">​</a></h3><p>除了页面跳转外可以指定其他链接。使用以下方式也有缺点，邮箱可能会被恶意用户采集到，所以有些用户使用 <code>houdunren#qq.com</code> 然后提示用户 <code>请将#改为@后发邮件</code>的提示形式。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;mailto:2300071698@qq.com&quot;</span><span style="color:#ABB2BF;">&gt;给后盾人发送邮件&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="拨打电话" tabindex="-1">拨打电话 <a class="header-anchor" href="#拨打电话" aria-label="Permalink to &quot;拨打电话&quot;">​</a></h3><p>点击以下链接后，手机会询问用户是否拨打电话。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;tel:99999999999&quot;</span><span style="color:#ABB2BF;">&gt;联系客服&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="下载文件" tabindex="-1">下载文件 <a class="header-anchor" href="#下载文件" aria-label="Permalink to &quot;下载文件&quot;">​</a></h3><p>默认情况下使用链接可以下载浏览器无法处理的文件，如果下载图片需要后台语言告之浏览器<code>mime</code>类型（可查看后盾人 PHP）相关课程。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">a</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;https://www.hdcms.com/HDCMS-201905072207.zip&quot;</span><span style="color:#ABB2BF;">&gt;下载HDCMS&lt;/</span><span style="color:#E06C75;">a</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,38)]))}const h=s(o,[["render",t]]);export{b as __pageData,h as default};
